<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/helpers.php';require_once __DIR__.'/../lib/admin.php';send_cors_headers();require_admin('reports.view');$db=get_db();$from=trim((string)($_GET['from']??gmdate('Y-m-01')));$to=trim((string)($_GET['to']??gmdate('Y-m-d')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)||$from>$to)json_response(422,['success'=>false,'message'=>'Report date range is invalid.']);$sales=$db->prepare('SELECT DATE(created_at) day,COUNT(*) orders,SUM(total_amount) gross_sales,SUM(discount_amount) discounts,SUM(tax_amount) taxes,SUM(shipping_amount) shipping FROM orders WHERE created_at>=:from AND created_at<DATE_ADD(:to,INTERVAL 1 DAY) AND payment_status IN ("paid","cod_pending") GROUP BY DATE(created_at) ORDER BY day');$sales->execute(['from'=>$from,'to'=>$to]);$vendors=$db->prepare('SELECT v.id,v.display_name,COUNT(DISTINCT g.id) orders,COALESCE(SUM(g.total_amount),0) sales,COALESCE(SUM(f.commission_amount),0) commission FROM vendors v LEFT JOIN vendor_order_groups g ON g.vendor_id=v.id AND g.created_at>=:from AND g.created_at<DATE_ADD(:to,INTERVAL 1 DAY) LEFT JOIN order_items oi ON oi.vendor_group_id=g.id LEFT JOIN order_item_financials f ON f.order_item_id=oi.id GROUP BY v.id ORDER BY sales DESC LIMIT 100');$vendors->execute(['from'=>$from,'to'=>$to]);json_response(200,['success'=>true,'range'=>['from'=>$from,'to'=>$to],'sales'=>$sales->fetchAll(),'vendors'=>$vendors->fetchAll()]);
